<script setup>
import { Head, router, useForm, usePage } from '@inertiajs/vue3';
import { ref } from 'vue';
defineProps({ studyPrograms:Array, faculties:Array });const page=usePage();const editingId=ref(null);const form=useForm({faculty_id:'',code:'',name:'',is_active:true});
function reset(){editingId.value=null;form.reset();form.clearErrors();form.is_active=true;}function edit(item){editingId.value=item.id;form.faculty_id=item.faculty_id;form.code=item.code;form.name=item.name;form.is_active=item.is_active;form.clearErrors();}function submit(){const opts={onSuccess:reset};editingId.value?form.put(`/master/program-studi/${editingId.value}`,opts):form.post('/master/program-studi',opts);}function remove(item){if(confirm(`Hapus program studi "${item.name}"?`))router.delete(`/master/program-studi/${item.id}`);}
</script>
<template><Head title="Master Program Studi"/><main class="min-h-screen bg-slate-50 p-6 text-slate-900 sm:p-10"><div class="mx-auto max-w-6xl"><a href="/dashboard" class="text-sm font-semibold text-indigo-700">← Dashboard</a><h1 class="mt-4 text-2xl font-bold">Master Program Studi</h1><p class="mt-1 text-sm text-slate-600">Setiap program studi terhubung ke satu fakultas.</p><p v-if="page.props.flash?.success" class="mt-4 rounded-lg bg-emerald-50 p-3 text-sm text-emerald-800">{{page.props.flash.success}}</p><p v-if="page.props.flash?.error" class="mt-4 rounded-lg bg-red-50 p-3 text-sm text-red-800">{{page.props.flash.error}}</p><div class="mt-6 grid gap-6 lg:grid-cols-2"><form @submit.prevent="submit" class="space-y-4 rounded-xl border bg-white p-5"><h2 class="font-semibold">{{editingId?'Ubah program studi':'Tambah program studi'}}</h2><label class="block text-sm font-medium">Fakultas<select v-model="form.faculty_id" required class="mt-1 w-full rounded-lg border p-2.5"><option value="">Pilih fakultas</option><option v-for="f in faculties" :key="f.id" :value="f.id">{{f.name}}</option></select><span class="text-sm text-red-700">{{form.errors.faculty_id}}</span></label><label class="block text-sm font-medium">Kode<input v-model="form.code" required maxlength="50" class="mt-1 w-full rounded-lg border p-2.5"/><span class="text-sm text-red-700">{{form.errors.code}}</span></label><label class="block text-sm font-medium">Nama program studi<input v-model="form.name" required maxlength="255" class="mt-1 w-full rounded-lg border p-2.5"/><span class="text-sm text-red-700">{{form.errors.name}}</span></label><label class="flex items-center gap-2 text-sm"><input v-model="form.is_active" type="checkbox"/> Aktif</label><div class="flex gap-2"><button :disabled="form.processing" class="rounded-lg bg-indigo-700 px-4 py-2 text-sm font-semibold text-white">Simpan</button><button v-if="editingId" type="button" @click="reset" class="rounded-lg border px-4 py-2 text-sm">Batal</button></div></form><section class="overflow-hidden rounded-xl border bg-white"><div class="border-b p-5 font-semibold">Daftar program studi ({{studyPrograms.length}})</div><p v-if="!studyPrograms.length" class="p-6 text-sm text-slate-500">Belum ada program studi.</p><div v-for="item in studyPrograms" :key="item.id" class="flex items-center justify-between gap-3 border-b p-4 last:border-0"><div><p class="font-semibold">{{item.name}}</p><p class="text-sm text-slate-500">{{item.code}} · {{item.faculty?.name || 'Fakultas tidak tersedia'}} · {{item.is_active?'Aktif':'Nonaktif'}}</p></div><div class="flex gap-2"><button @click="edit(item)" class="rounded border px-3 py-1.5 text-sm">Ubah</button><button @click="remove(item)" class="rounded border border-red-200 px-3 py-1.5 text-sm text-red-700">Hapus</button></div></div></section></div></div></main></template>
